/**
 * App.jsx - entry point.
 *
 * Phase 0 (P0.6):
 *   1. Chi seed khi USE_MOCKS=true (da chot o muc 8b cua plan).
 *      Ly do: neu app vua co du lieu seed gia vua co du lieu that tu API,
 *      rat kho chan doan "3 item trong list - tu API hay tu seed?".
 *
 * ΓÜá∩╕Å File nay KHONG immutable. Moi sprint them 1 dong import Real service
 * o vung "Sprint import-side-effect" ben duoi khi service do da duoc tao.
 * Chi them DUNG 1 DONG - dung viet import cho service chua ton tai
 * (import file khong co = app crash ngay).
 *
 * ΓÜá∩╕Å KHONG duoc them `eslint-disable` o day. File nay la entry point,
 *   moi sprint deu cham vao - tat lint se bien mat lop bao ve o noi can nhat.
 */

import React, { useEffect, useState } from 'react';
import { View, ActivityIndicator, StatusBar, StyleSheet } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import {
  useFonts,
  PlusJakartaSans_400Regular,
  PlusJakartaSans_500Medium,
  PlusJakartaSans_600SemiBold,
  PlusJakartaSans_700Bold,
  PlusJakartaSans_800ExtraBold,
} from '@expo-google-fonts/plus-jakarta-sans';
import Toast from 'react-native-toast-message';
import { AppProviders } from './src/providers/AppProviders';
import { RootNavigator } from './src/presentation/navigation/RootNavigator';
import { useAuthStore } from './src/shared/stores/useAuthStore';
import { useThemeStore } from './src/shared/stores/useThemeStore';
import { useLanguageStore } from './src/shared/stores/useLanguageStore';
import { AppColors } from './src/presentation/theme/colors';
import { initAppShell } from './src/data/appInit';

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// Sprint import-side-effect
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
// Mß╗ùi Real*Service tß╗▒ ─æ─âng k├╜ v├áo ServiceRegistry bß║▒ng side-effect import.
// ServiceProvider.jsx ─æß╗ìc registry ─æ├│, n├¬n chß╗ë cß║ºn import l├á domain ─æ├│
// tß╗▒ chuyß╗ân tß╗½ mock sang thß║¡t - kh├┤ng sß╗¡a ServiceProvider/useServiceHooks.
//
// C├üCH D├ÖNG (mß╗ùi sprint th├¬m ─É├ÜNG 1 D├ÆNG, ngay d╞░ß╗¢i comment n├áy):
//   Sprint A1:  import './src/data/services/real/RealAuthService';
//   Sprint A2:  import './src/data/services/real/RealUserService';
//   Sprint B1:  import './src/data/services/real/realFridge.register';
//
// ΓÜá∩╕Å CHß╗ê import SAU KHI file ─æ├│ ─æ├ú ─æ╞░ß╗úc tß║ío trong src/data/services/real/.
//    Import file kh├┤ng tß╗ôn tß║íi = app crash ngay khi khß╗ƒi ─æß╗Öng
//    ("Unable to resolve module"), kß╗â cß║ú khi USE_MOCKS=true.
//    Phase 0 ch╞░a c├│ Real*Service n├áo (tß║ío ß╗ƒ A1/B1 trß╗ƒ ─æi) n├¬n v├╣ng n├áy
//    ─æß╗â trß╗æng l├á ─æ├║ng.
//
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// B1 ΓÇö Fridge CRUD (─æ├ú tß║ío file, ─æ─âng k├╜ key 'fridgeService')
//
// ΓÜá∩╕Å V├î SAO IMPORT ß╗₧ ─É├éY M├Ç KH├öNG ß╗₧ SERVICE PROVIDER:
// `ServiceProvider.jsx` l├á file IMMUTABLE tß╗½ P0.5 (kh├┤ng sß╗¡a ─æ╞░ß╗úc).
// C╞í chß║┐ registry y├¬u cß║ºu side-effect import ß╗ƒ entry point.
//
// T├üC Dß╗ñNG:
//   USE_MOCKS=false -> `resolveServices()` bß╗ìc `RealFridgeService` trong
//   `withFallback()` -> domain 'fridgeService' gß╗ìi BE thß║¡t.
//   USE_MOCKS=true  -> vß║½n l├á mock (kh├┤ng ─æß╗òi h├ánh vi UI design).
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
import './src/data/services/real/RealFridgeService';
// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

// Sprint A1: ─æ─âng k├╜ RealAuthService (side-effect registerService).
// Auth l├á domain NHß║áY Cß║óM - kh├┤ng bao giß╗¥ fallback sang mock (xem ServiceRegistry).
import './src/data/services/real/RealAuthService';

// Sprint A2: ─æ─âng k├╜ RealUserService (profile / preferences / allergies / onboarding).
import './src/data/services/real/RealUserService';

export default function App() {
  const [fontsLoaded] = useFonts({
    PlusJakartaSans_400Regular,
    PlusJakartaSans_500Medium,
    PlusJakartaSans_600SemiBold,
    PlusJakartaSans_700Bold,
    PlusJakartaSans_800ExtraBold,
  });

  const [isDbReady, setIsDbReady] = useState(false);

  const initAuth = useAuthStore((s) => s.initAuth);
  const initTheme = useThemeStore((s) => s.initTheme);
  const initLocale = useLanguageStore((s) => s.initLocale);

  useEffect(() => {
    (async () => {
      initAuth();
      initTheme();
      initLocale();
      // P0.6: chi seed khi USE_MOCKS=true (xem src/data/appInit.test.js)
      await initAppShell();
      setIsDbReady(true);
    })();
  }, []);

  if (!fontsLoaded || !isDbReady) {
    return (
      <View style={styles.loading}>
        <ActivityIndicator size="large" color={AppColors.primary} />
      </View>
    );
  }

  return (
    <AppProviders>
      <NavigationContainer>
        <RootNavigator />
        <StatusBar barStyle="dark-content" />
      </NavigationContainer>
      <Toast />
    </AppProviders>
  );
}

const styles = StyleSheet.create({
  loading: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: AppColors.lightBackground,
  },
});

/**
 * Qu├⌐t tß║Ñt cß║ú import named trong src/ v├á kiß╗âm tra:
 *   1. File ─æ├¡ch c├│ tß╗ôn tß║íi kh├┤ng?
 *   2. Named export ─æ├│ c├│ ─æ╞░ß╗úc export thß║¡t kh├┤ng?
 *
 * ─É├óy ch├¡nh l├á lß╗¢p bug g├óy crash runtime kiß╗âu
 * "Cannot read property 'X' of undefined" (P0.7.1).
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const SRC = path.join(ROOT, 'src');

const files = [];
(function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (e.name === 'node_modules' || e.name === '__tests__') continue;
      walk(p);
    } else if (/\.(js|jsx)$/.test(e.name)) {
      files.push(p);
    }
  }
})(SRC);

const EXT = ['.js', '.jsx', '/index.js', '/index.jsx', ''];

function resolve(fromFile, spec) {
  if (!spec.startsWith('.')) return null; // package - skip
  if (!spec.startsWith('.') && !spec.startsWith('/')) return null;
  const base = path.resolve(path.dirname(fromFile), spec);
  for (const ext of EXT) {
    const cand = base + ext;
    if (fs.existsSync(cand) && fs.statSync(cand).isFile()) return cand;
  }
  // ./foo -> ./foo.jsx  and  ./foo.js -> ./foo.jsx
  if (base.endsWith('.js')) {
    const alt = base.replace(/\.js$/, '.jsx');
    if (fs.existsSync(alt)) return alt;
  }
  return null;
}

// Tr├¡ch named exports tß╗½ file target
function getExports(file) {
  const src = fs.readFileSync(file, 'utf8');
  const names = new Set();

  // export const X / export let / export var / export function X / export class X
  const decl = /export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)/g;
  let m;
  while ((m = decl.exec(src))) names.add(m[1]);

  const fn = /export\s+(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/g;
  while ((m = fn.exec(src))) names.add(m[1]);

  const cls = /export\s+class\s+([A-Za-z_$][\w$]*)/g;
  while ((m = cls.exec(src))) names.add(m[1]);

  // export { A, B as C }
  const braced = /export\s*\{([^}]*)\}/g;
  while ((m = braced.exec(src))) {
    m[1]
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean)
      .forEach((s) => {
        const parts = s.split(/\s+as\s+/);
        names.add((parts[1] || parts[0]).trim());
      });
  }

  // export * from './x'  -> lß║Ñy exports cß╗ºa file con
  const star = /export\s+\*\s+from\s+['"]([^'"]+)['"]/g;
  while ((m = star.exec(src))) {
    const t = resolve(file, m[1]);
    if (t) getExports(t).forEach((n) => names.add(n));
  }

  if (/export\s+default/.test(src)) names.add('default');
  return names;
}

// Tr├¡ch import statements
function parseImports(file) {
  const src = fs.readFileSync(file, 'utf8');
  const out = [];
  const re = /import\s+([^;'"]+?)\s+from\s+['"]([^'"]+)['"]/g;
  let m;
  while ((m = re.exec(src))) {
    const clause = m[1].trim();
    const spec = m[2];
    if (/^\*\s+as\s+/.test(clause)) continue; // namespace import - lu├┤n hß╗úp lß╗ç

    const braceMatch = clause.match(/\{([^}]*)\}/);
    if (!braceMatch) continue; // default import - kh├┤ng kiß╗âm tra named

    const named = braceMatch[1]
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean)
      .map((s) => s.split(/\s+as\s+/)[0].trim())
      .filter((s) => s && s !== 'type');
    out.push({ spec, named, line: src.slice(0, m.index).split('\n').length });
  }
  return out;
}

const problems = [];
let checked = 0;

for (const f of files) {
  let imports;
  try {
    imports = parseImports(f);
  } catch (e) {
    continue;
  }
  for (const imp of imports) {
    if (!imp.named.length) continue;
    // Bß╗Å qua package import (react, axios, lucide-react-native...) -
    // kh├┤ng phß║úi bug named-export trong codebase.
    if (!imp.spec.startsWith('.')) continue;
    const target = resolve(f, imp.spec);
    checked += imp.named.length;
    const rel = path.relative(ROOT, f);
    if (!target) {
      problems.push({
        kind: 'MISSING_FILE',
        file: rel,
        line: imp.line,
        detail: `import tß╗½ "${imp.spec}" ΓÇö FILE KH├öNG Tß╗ÆN Tß║áI`,
      });
      continue;
    }
    const exports = getExports(target);
    const bad = imp.named.filter((n) => !exports.has(n));
    if (bad.length) {
      problems.push({
        kind: 'MISSING_EXPORT',
        file: rel,
        line: imp.line,
        detail: `import { ${bad.join(', ')} } tß╗½ "${imp.spec}" ΓÇö KH├öNG ─æ╞░ß╗úc export (target: ${path
          .relative(ROOT, target)
          .replace(/\\/g, '/')})`,
      });
    }
  }
}

console.log(`─É├ú kiß╗âm tra ${files.length} file, ${checked} named import.`);
console.log(`Vß║Ñn ─æß╗ü: ${problems.length}\n`);
const byKind = {};
problems.forEach((p) => {
  byKind[p.kind] = byKind[p.kind] || [];
  byKind[p.kind].push(p);
});
for (const [k, list] of Object.entries(byKind)) {
  console.log(`ΓöÇΓöÇ ${k} (${list.length}) ΓöÇΓöÇ`);
  list.forEach((p) => console.log(`  ${p.file}:${p.line}\n     ${p.detail}`));
  console.log('');
}

