/**
 * TEST CHß╗ÉT Hß╗ÆI QUY ΓÇö `SafeService` proxy phß║úi expose Mß╗îI method cß╗ºa real service.
 *
 * Sprint A3 (24/10).
 *
 * ΓÜá∩╕Å Bß╗ÉI Cß║óNH:
 *   `SafeService.withFallback(real, mock)` chß╗ë expose method c├│ trong prototype
 *   chain cß╗ºa MOCK (xem `SafeService.js` -> `collectNames(mockService)`).
 *   Method chß╗ë c├│ ß╗ƒ REAL sß║╜ **biß║┐n mß║Ñt khß╗Åi `useServices()`** -> UI gß╗ìi
 *   `service.method()` -> `undefined is not a function` -> CRASH.
 *
 *   Bug n├áy ─æ├ú xß║úy ra thß║¡t ß╗ƒ A3: `RealUserService` c├│ nhiß╗üu method m├á
 *   `MockUserService` kh├┤ng c├│ -> m├án "Quß║ún l├╜ g├│i" + "Quß║ún l├╜ gia ─æ├¼nh"
 *   CRASH khi `USE_MOCKS=false`.
 *
 *   Test n├áy qu├⌐t Tß║ñT Cß║ó domain ─É─éNG K├¥ thß║¡t (`registerService(...)`), kh├┤ng
 *   chß╗ë A3 -> bß║»t ─æ╞░ß╗úc bug t╞░╞íng lai cß╗ºa B2/B3/B4 (Dev B th├¬m method mß╗¢i v├áo
 *   real m├á qu├¬n th├¬m v├áo mock).
 *
 * ΓÜá∩╕Å V├î SAO ─Éß╗îC SOURCE THAY V├î IMPORT:
 *   `Real*Service` gß╗ìi `registerService(...)` ß╗ƒ module scope (side-effect) v├á
 *   import `ApiClient` -> c├│ thß╗â chß║ím network/token khi require. Ta chß╗ë ─æß╗ìc
 *   source bß║▒ng `fs` ─æß╗â lß║Ñy DANH S├üCH T├èN METHOD, kh├┤ng instantiate.
 */

import fs from 'fs';
import path from 'path';

import { MockUserService } from '../../mock/MockUserService';
import { MockFridgeService } from '../../mock/MockFridgeService';
import { MockAuthService } from '../../mock/MockAuthService';

import { IUserService } from '../../../interfaces/IUserService';
import { IFridgeService } from '../../../interfaces/IFridgeService';
import { IAuthService } from '../../../interfaces/IAuthService';

/** Thu tß║¡p t├¬n method tr├¬n to├án bß╗Ö prototype chain (giß╗æng `collectNames`). */
const collectMethodNames = (obj) => {
  const names = new Set();
  let current = obj;
  while (current && current !== Object.prototype) {
    for (const name of Object.getOwnPropertyNames(current)) {
      if (name === 'constructor') continue;
      if (typeof obj[name] === 'function') names.add(name);
    }
    current = Object.getPrototypeOf(current);
  }
  return names;
};

/**
 * ─Éß╗ìc class `Real*Service` tß╗½ file m├á KH├öNG cß║ºn import (tr├ính side-effect).
 * Chß╗ë lß║Ñy method PUBLIC (bß╗Å `_` prefix) ΓÇö method private kh├┤ng ai gß╗ìi tß╗½ UI.
 */
const RESERVED_WORDS = new Set([
  'constructor',
  'if',
  'for',
  'while',
  'switch',
  'catch',
  'return',
  'function',
  'class',
  'do',
  'else',
  'try',
]);

const readRealMethodNames = (fileName) => {
  const filePath = path.join(__dirname, '..', fileName);
  const src = fs.readFileSync(filePath, 'utf8');
  const names = new Set();
  const re = /^\s{2}(?:async\s+)?(\w+)\s*\(/gm;
  let m;
  while ((m = re.exec(src))) {
    const name = m[1];
    if (name.startsWith('_')) continue;
    if (RESERVED_WORDS.has(name)) continue;
    names.add(name);
  }
  return names;
};

/**
 * Danh s├ích domain ─É─éNG K├¥ THß║¼T (khß╗¢p `registerService(...)` trong
 * `src/data/services/real/*.js`). ─É├óy l├á nguß╗ôn sß╗▒ thß║¡t cß╗ºa `useServices()`.
 */
const DOMAINS = [
  {
    label: 'userService',
    realFile: 'RealUserService.js',
    mock: new MockUserService(),
    iface: IUserService,
  },
  {
    label: 'fridgeService',
    realFile: 'RealFridgeService.js',
    mock: new MockFridgeService(),
    iface: IFridgeService,
  },
  {
    label: 'authService',
    realFile: 'RealAuthService.js',
    mock: new MockAuthService(),
    iface: IAuthService,
  },
];

describe('SafeService proxy - moi method cua real deu phai co o mock hoac interface', () => {
  it.each(DOMAINS)('$label: khong co method nao cua real bi mat khi proxy', (domain) => {
    const realMethods = readRealMethodNames(domain.realFile);
    const mockMethods = collectMethodNames(domain.mock);
    const ifaceMethods = collectMethodNames(domain.iface);

    const missing = [...realMethods].filter(
      (m) => !mockMethods.has(m) && !ifaceMethods.has(m)
    );

    expect({
      domain: domain.label,
      missing,
    }).toEqual({ domain: domain.label, missing: [] });
  });

  it('mß╗ìi domain ─æß╗üu tß╗ôn tß║íi file real service t╞░╞íng ß╗⌐ng', () => {
    for (const domain of DOMAINS) {
      const filePath = path.join(__dirname, '..', domain.realFile);
      expect(fs.existsSync(filePath)).toBe(true);
    }
  });

  it('mß╗ùi domain ─æß╗üu ─æ─âng k├╜ ─æ├║ng 1 key trong ServiceRegistry', () => {
    for (const domain of DOMAINS) {
      const filePath = path.join(__dirname, '..', domain.realFile);
      const src = fs.readFileSync(filePath, 'utf8');
      expect(src).toContain(`registerService('${domain.label}'`);
    }
  });
});

