        ios_backgroundColor="#9DA8A0"
      />
    </View>
  );
};

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: sp(14),
  },
  body: {
    flex: 1,
  },
  label: {
    fontFamily: FontFamily.regular,
  },
  description: {
    fontFamily: FontFamily.regular,
    marginTop: sp(2),
  },
});

