/**
 * FridgeItem
 *
 * Row hiß╗ân thß╗ï 1 nguy├¬n liß╗çu trong tß╗º lß║ính:
 * - Icon (theo category: vegetable/meat/dairy/fruit/other)
 * - Name + quantity
 * - Expiry badge vß╗¢i m├áu sß║»c (fresh: xanh, expiring: cam, expired: ─æß╗Å)
 * - Press handler
 */

import React from 'react';
import { View, Text, Pressable, Image, StyleSheet } from 'react-native';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp } from '../../utils/responsive';
import { FontFamily, FontWeights } from '../../theme/typography';
import { AlertCircle, Carrot, Beef, Egg, Apple, Leaf } from 'lucide-react-native';
import { useTranslation } from 'react-i18next';
import { getDaysToExpiry } from '../../utils/fridgeDates';

const CATEGORY_ICON = {
  vegetable: Carrot,
  meat: Beef,
  dairy: Egg,
  fruit: Apple,
  other: Leaf,
};

const CATEGORY_COLOR = {
  vegetable: '#4CAF50',
  meat: '#E57373',
  dairy: '#FFB300',
  fruit: '#FF7043',
  other: '#9E9E9E',
};

const STATUS_COLOR = {
  fresh: { bg: '#E8F5E9', fg: '#1B5E20', darkBg: '#1B3324', darkFg: AppColors.primaryLight },
  expiring: { bg: '#FFF3E0', fg: '#E65100', darkBg: '#3D2E1A', darkFg: '#FFB74D' },
  expired: { bg: '#FFEBEE', fg: '#B71C1C', darkBg: '#3D1F1A', darkFg: '#FF8A80' },
};

const formatExpiry = (days, isEn) => {
  // `days === null` = kh├┤ng c├│ hß║ín d├╣ng (BE trß║ú `expiresAt: null`, hoß║╖c mock
  // ch╞░a g├ín). Kh├┤ng phß║úi l├á "─É├ú hß║┐t hß║ín" -> hiß╗çn "Kh├┤ng r├╡ hß║ín" cho ─æ├║ng.
  if (days === null) return isEn ? 'No expiry' : 'Kh├┤ng r├╡ hß║ín';
  if (days < 0) return isEn ? 'Expired' : '─É├ú hß║┐t hß║ín';
  if (days === 0) return isEn ? 'Today' : 'H├┤m nay';
  if (days === 1) return isEn ? 'Tomorrow' : 'Ng├áy mai';
  return isEn ? `${days}d` : `${days} ng├áy`;
};

const IMAGE_MAP = {
  food_tomato: require('../../../../assets/images/food_tomato.png'),
  food_milk: require('../../../../assets/images/food_milk.png'),
  food_pork: require('../../../../assets/images/food_pork.png'),
  food_bokchoy: require('../../../../assets/images/food_bokchoy.png'),
};

export const FridgeItem = ({ item, onPress, style }) => {
  const { isDark } = useTheme();
  const { t, i18n } = useTranslation();
  const isEn = i18n.language === 'en';

  const Icon = CATEGORY_ICON[item.category] || Leaf;
  const iconColor = CATEGORY_COLOR[item.category] || CATEGORY_COLOR.other;
  const days = getDaysToExpiry(item.expiryDate);
  // `days === null` (kh├┤ng c├│ hß║ín d├╣ng) -> coi nh╞░ c├▓n t╞░╞íi, kh├┤ng phß║úi expired.
  const status =
    item.status ||
    (days === null ? 'fresh' : days < 0 ? 'expired' : days <= 3 ? 'expiring' : 'fresh');
  const colorScheme = STATUS_COLOR[status];
  const badgeBg = isDark ? colorScheme.darkBg : colorScheme.bg;
  const badgeFg = isDark ? colorScheme.darkFg : colorScheme.fg;

  const imageSource = item.image && IMAGE_MAP[item.image] ? IMAGE_MAP[item.image] : null;

  return (
    <Pressable
      onPress={() => onPress && onPress(item)}
      style={({ pressed }) => [
        {
          opacity: pressed ? 0.85 : 1,
        },
        style,
      ]}
    >
      <View
        style={[
          styles.row,
          {
            backgroundColor: isDark ? '#19271E' : '#F4F7F4',
            borderColor: status === 'expiring' || status === 'expired'
              ? badgeFg
              : 'transparent',
            borderWidth: status === 'expiring' || status === 'expired' ? 1 : 0,
          },
        ]}
      >
        <View
          style={[
            styles.iconWrap,
            { backgroundColor: iconColor + (isDark ? '33' : '22') },
          ]}
        >
          {imageSource ? (
            <Image source={imageSource} style={styles.image} resizeMode="contain" />
          ) : (
            <Icon color={iconColor} size={22} strokeWidth={2.2} />
          )}
        </View>
        <View style={{ flex: 1, marginLeft: sp(12) }}>
          <Text
            style={[
              styles.name,
              { color: isDark ? '#FFFFFF' : AppColors.textPrimary },
            ]}
            numberOfLines={1}
          >
            {item.name}
          </Text>
          <Text
            style={[
              styles.qty,
              { color: isDark ? AppColors.darkTextSecondary : AppColors.textSecondary },
            ]}
            numberOfLines={1}
          >
            {item.quantity} {item.unit}
          </Text>
        </View>
        <View style={[styles.badge, { backgroundColor: badgeBg }]}>
          {status === 'expired' || status === 'expiring' ? (
            <AlertCircle color={badgeFg} size={11} strokeWidth={2.5} />
          ) : null}
          <Text
            style={[
              styles.badgeText,
              { color: badgeFg, marginLeft: status !== 'fresh' ? sp(3) : 0 },
            ]}
          >
            {formatExpiry(days, isEn)}
          </Text>
        </View>
      </View>
    </Pressable>
  );
};

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: sp(14),
    borderRadius: sp(14),
  },
  iconWrap: {
    width: sp(44),
    height: sp(44),
    borderRadius: sp(12),
    alignItems: 'center',
    justifyContent: 'center',
  },
  image: {
    width: sp(36),
    height: sp(36),
  },
  name: {
    fontSize: sp(15),
    fontFamily: FontFamily.semibold,
    fontWeight: FontWeights.semibold,
  },
  qty: {
    fontSize: sp(12),
    fontFamily: FontFamily.regular,
    marginTop: sp(2),
  },
  badge: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: sp(8),
    paddingVertical: sp(4),
    borderRadius: sp(10),
  },
  badgeText: {
    fontSize: sp(11),
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
  },
});

/**
 * CookingSuggestionsSection
 *
 * Redesign (flat card, kh├┤ng gradient/shadow ΓÇö ─æß╗ông bß╗Ö GreetingBanner +
 * PremiumBanner + WeeklyStatisticsSection):
 * - Bß╗ìc ngo├ái l├á 1 card lß╗¢n c├│ header "C├íc bß╗»a ─ân trong ng├áy h├┤m nay"
 * - B├¬n trong: danh s├ích dß╗ìc, mß╗ùi m├│n 1 card ngang
 *   ΓÇó H├áng 1: tag bß╗»a (s├íng/tr╞░a/tß╗æi) + trß║íng th├íi li├¬n quan ─æß║┐n nß║Ñu
 *   ΓÇó H├áng 2: t├¬n m├│n (lß╗¢n) + ch├║ th├¡ch nhß╗Å (sß╗æ ng╞░ß╗¥i, thß╗¥i gian nß║Ñu)
 *   ΓÇó H├áng 3: 2 button "Xem c├┤ng thß╗⌐c" + "─Éß╗òi m├│n bß║▒ng AI"
 * - ß║ónh ─æß╗â trß╗æng (null) ΓÇö layout ─æ├ú sß║╡n s├áng, chß╗¥ thay ß║únh
 */

import React from 'react';
import { View, Text, Image, StyleSheet, Pressable } from 'react-native';
import { useTheme } from '../../theme/ThemeContext';
import { AppColors } from '../../theme/colors';
import { sp } from '../../utils/responsive';
import { FontFamily, FontWeights } from '../../theme/typography';
import { Users, Clock, Sparkles, ChevronRight } from 'lucide-react-native';
import { useTranslation } from 'react-i18next';
import { useRecipeSuggestions } from '../../hooks/useServiceHooks';
import { Skeleton } from '../common/Skeleton';
import { EmptyState } from '../common/EmptyState';
import { ErrorState } from '../common/ErrorState';

// ß║ónh minh hoß║í tß╗½ng m├│n ΓÇö ─æß╗â trß╗æng tr╞░ß╗¢c khi c├│ asset.
const MEAL_ART = null;

// Map index cß╗ºa suggestion -> bß╗»a ─ân (data mock c├│ 4 m├│n t╞░╞íng ß╗⌐ng
// s├íng / tr╞░a / tß╗æi / phß╗Ñ). Khi nß╗æi API thß║¡t, lß║Ñy `mealType` tß╗½ response.
const MEAL_SLOTS = [
  { key: 'mealBreakfast', accent: AppColors.accentOrange },
  { key: 'mealLunch', accent: AppColors.primary },
  { key: 'mealDinner', accent: AppColors.forestAccent },
  { key: 'mealSnack', accent: AppColors.textSecondary },
];

export const CookingSuggestionsSection = ({ onRecipeTap, onSwapTap }) => {
  const { isDark } = useTheme();
  const { t } = useTranslation();
  const { data: suggestions, loading, error, refetch } = useRecipeSuggestions();

  const surfaceColor = isDark ? '#19271E' : '#FFFFFF';
  const borderColor = isDark ? '#2E4D36' : '#A5E69C';
  const textPrimary = isDark ? '#FFFFFF' : AppColors.textPrimary;

  const header = (
    <View style={styles.headerRow}>
      <View style={[styles.headerIcon, { backgroundColor: isDark ? '#233629' : AppColors.accentGreen }]}>
        <Sparkles color={isDark ? AppColors.primaryLight : AppColors.forestAccent} size={16} />
      </View>
      <Text style={[styles.title, { color: textPrimary }]} numberOfLines={1}>
        {t('home.mealsToday')}
      </Text>
    </View>
  );

  // Loading state
  if (loading) {
    return (
      <View style={styles.wrap}>
        <View style={[styles.surface, { backgroundColor: surfaceColor, borderColor }]}>
          {header}
          {[0, 1, 2].map((i) => (
            <View
              key={i}
              style={[styles.mealCard, { backgroundColor: surfaceColor, borderColor, marginTop: sp(10) }]}
            >
              <Skeleton width={sp(70)} height={sp(18)} borderRadius={sp(9)} />
              <View style={styles.mealMainRow}>
                <Skeleton width={sp(64)} height={sp(64)} borderRadius={sp(12)} />
                <View style={styles.mealInfo}>
                  <Skeleton width="85%" height={sp(14)} />
                  <Skeleton width="60%" height={sp(10)} style={{ marginTop: sp(6) }} />
                </View>
              </View>
              <View style={styles.mealBtnRow}>
                <Skeleton width="48%" height={sp(34)} borderRadius={sp(17)} />
                <Skeleton width="48%" height={sp(34)} borderRadius={sp(17)} />
              </View>
            </View>
          ))}
        </View>
      </View>
    );
  }

  // Error state
  if (error) {
    return (
      <View style={styles.wrap}>
        <View style={[styles.surface, { backgroundColor: surfaceColor, borderColor }]}>
          {header}
          <ErrorState onRetry={refetch} />
        </View>
      </View>
    );
  }

  // Empty state
  if (!suggestions || suggestions.length === 0) {
    return (
      <View style={styles.wrap}>
        <View style={[styles.surface, { backgroundColor: surfaceColor, borderColor }]}>
          {header}
          <EmptyState emoji="≡ƒì│" title={t('home.noData')} hint={t('home.tipMoreRecipes')} />
        </View>
      </View>
    );
  }

  return (
    <View style={styles.wrap}>
      <View style={[styles.surface, { backgroundColor: surfaceColor, borderColor }]}>
        {header}

        {suggestions.map((recipe, i) => (
          <MealCard
            key={recipe.id}
            isDark={isDark}
            t={t}
            recipe={recipe}
            index={i}
            slot={MEAL_SLOTS[i % MEAL_SLOTS.length]}
            onRecipeTap={onRecipeTap}
            onSwapTap={onSwapTap}
          />
        ))}
      </View>
    </View>
  );
};

const MealCard = ({ isDark, t, recipe, slot, index, onRecipeTap, onSwapTap }) => {
  const accent = slot?.accent || AppColors.primary;
  const borderColor = isDark ? '#2E4D36' : '#A5E69C';
  const surfaceColor = isDark ? '#19271E' : '#FFFFFF';
  const textPrimary = isDark ? '#FFFFFF' : AppColors.textPrimary;
  const textSecondary = isDark ? AppColors.darkTextSecondary : AppColors.textSecondary;
  const tint = isDark ? '#233629' : AppColors.accentGreen;
  const fg = isDark ? AppColors.primaryLight : AppColors.primaryLight;

  return (
    <View style={[styles.mealCard, { backgroundColor: surfaceColor, borderColor }]}>
      {/* H├áng 1: tag bß╗»a + trß║íng th├íi nß║Ñu */}
      <View style={styles.mealTopRow}>
        <View style={[styles.mealTag, { backgroundColor: tint, borderColor: accent }]}>
          <Text style={[styles.mealTagText, { color: fg }]}>
            {slot ? t(slot.key) : t('meal.mealType')}
          </Text>
        </View>
        {recipe.cooked ? (
          <View style={[styles.statusChip, { backgroundColor: isDark ? '#1E3A25' : '#E8F5E9' }]}>
            <Text style={[styles.statusText, { color: AppColors.primary }]}>
              {t('home.alreadyCooked')}
            </Text>
          </View>
        ) : (
          <View style={[styles.statusChip, { backgroundColor: isDark ? '#3A2A1E' : '#FFF3E0' }]}>
            <Text style={[styles.statusText, { color: AppColors.accentOrange }]}>
              {t('home.toCook')}
            </Text>
          </View>
        )}
      </View>

      <View style={styles.mealMainRow}>
        <View style={styles.mealInfo}>
          <Text style={[styles.mealName, { color: textPrimary }]} numberOfLines={2}>
            {recipe.name}
          </Text>
          <View style={styles.mealMetaRow}>
            <Users color={textSecondary} size={12} />
            <Text style={[styles.mealMetaText, { color: textSecondary }]}>
              {recipe.servings || 2} {t('home.people')}
            </Text>
            <Clock color={textSecondary} size={12} style={styles.mealMetaIcon} />
            <Text style={[styles.mealMetaText, { color: textSecondary }]}>
              {recipe.cookTime} {t('home.minutes')}
            </Text>
          </View>
        </View>
      </View>

      <View style={styles.mealBtnRow}>
        <Pressable
          onPress={() => onRecipeTap && onRecipeTap(recipe, index)}
          style={({ pressed }) => [
            styles.mealBtn,
            styles.mealBtnGhost,
            { borderColor, opacity: pressed ? 0.7 : 1 },
          ]}
        >
          <Text style={[styles.mealBtnGhostText, { color: fg }]} numberOfLines={1}>
            {t('home.viewRecipe')}
          </Text>
          <ChevronRight color={isDark ? '#ffff' : '#4CAF50'} size={14} strokeWidth={2.5} />
        </Pressable>

        <Pressable
          onPress={() => onSwapTap && onSwapTap(recipe, index)}
          style={({ pressed }) => [
            styles.mealBtn,
            {
              backgroundColor: isDark ? AppColors.primaryLight : AppColors.primary,
              opacity: pressed ? 0.8 : 1,
            },
          ]}
        >
          <Sparkles color={fg} size={13} strokeWidth={2.5} />
          <Text style={[styles.mealBtnText, { color: isDark ? '#0E1611' : '#FFFFFF' }]}>
            {t('home.swapWithAI')}
          </Text>
        </Pressable>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  wrap: {
    marginTop: sp(20),
    marginHorizontal: sp(20),
  },
  // Card lß╗¢n bß╗ìc ngo├ái: nß╗ün + viß╗ün t─⌐nh, KH├öNG shadow.
  surface: {
    borderRadius: sp(20),
    borderWidth: sp(1.5),
    padding: sp(14),
  },
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: sp(12),
  },
  headerIcon: {
    width: sp(30),
    height: sp(30),
    borderRadius: sp(10),
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: sp(8),
  },
  title: {
    flex: 1,
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
    fontSize: sp(15),
  },
  mealCard: {
    borderRadius: sp(16),
    borderWidth: 1,
    padding: sp(12),
    marginTop: sp(10),
  },
  // H├áng 1: tag bß╗»a + trß║íng th├íi nß║Ñu
  mealTopRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: sp(10),
  },
  mealTag: {
    paddingHorizontal: sp(8),
    paddingVertical: sp(3),
    borderRadius: sp(9),
    borderWidth: 1,
  },
  mealTagText: {
    fontSize: sp(10),
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
  },
  statusChip: {
    paddingHorizontal: sp(8),
    paddingVertical: sp(3),
    borderRadius: sp(9),
  },
  statusText: {
    fontSize: sp(10),
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
  },
  // H├áng 2: ß║únh + th├┤ng tin
  mealMainRow: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  mealInfo: {
    flex: 1,
    marginLeft: sp(12),
  },
  mealName: {
    fontFamily: FontFamily.bold,
    fontWeight: FontWeights.bold,
    fontSize: sp(15),
    lineHeight: sp(20),
  },
  mealMetaRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginTop: sp(5),
  },
  mealMetaIcon: {
    marginLeft: sp(10),
  },
  mealMetaText: {
    fontSize: sp(11),
    fontFamily: FontFamily.medium,
    fontWeight: FontWeights.medium,
    marginLeft: sp(4),
  },
  // H├áng 3: 2 button
  mealBtnRow: {
    flexDirection: 'row',
    gap: sp(8),
