// Map LanguageProvider trong Flutter
import { create } from 'zustand';
import { getLocales } from 'expo-localization';

const STORAGE_KEY = 'language';

let mmkv;
try {
  const { MMKV } = require('react-native-mmkv');
  mmkv = new MMKV();
} catch (e) {
  const memStore = {};
  mmkv = {
    getString: (k) => memStore[k],
    set: (k, v) => {
      memStore[k] = v;
    },
  };
}

const detectInitialLocale = () => {
  try {
    const locales = getLocales();
    if (locales && locales[0] && locales[0].languageCode === 'en') {
      return 'en';
    }
  } catch (e) {
    // ignore
  }
  return 'vi'; // Default Vietnamese
};

export const useLanguageStore = create((set) => ({
  locale: detectInitialLocale(),
  initLocale: () => {
    try {
      const saved = mmkv.getString(STORAGE_KEY);
      if (saved) {
        set({ locale: saved });
      }
    } catch (e) {
      // ignore
    }
  },
  setLocale: (lang) => {
    try {
      mmkv.set(STORAGE_KEY, lang);
    } catch (e) {
      // ignore
    }
    set({ locale: lang });
  },
  toggleLocale: () => {
    set((state) => {
      const next = state.locale === 'vi' ? 'en' : 'vi';
      try {
        mmkv.set(STORAGE_KEY, next);
      } catch (e) {
        // ignore
      }
      return { locale: next };
    });
  },
}));

// Map ThemeProvider trong Flutter
import { create } from 'zustand';

const STORAGE_KEY = 'themeMode';

let mmkv;
try {
  const { MMKV } = require('react-native-mmkv');
  mmkv = new MMKV();
} catch (e) {
  // MMKV not available - fallback to in-memory
  const memStore = {};
  mmkv = {
    getString: (k) => memStore[k],
    set: (k, v) => {
      memStore[k] = v;
    },
  };
}

export const useThemeStore = create((set) => ({
  // Mß║╖c ─æß╗ïnh 'light': thiß║┐t kß║┐ gradient nß╗ün (AppGradients) ─æ╞░ß╗úc dß╗▒ng cho nß╗ün
  // s├íng tr╞░ß╗¢c. 'system' khiß║┐n m├íy ─æang ß╗ƒ dark mode mß╗ƒ app ra l├á tß╗æi ngay,
  // kh├┤ng ─æ├║ng ├╜ ─æß╗ô sß║ún phß║⌐m. Ng╞░ß╗¥i d├╣ng vß║½n ─æß╗òi ─æ╞░ß╗úc trong App Settings.
  themeMode: 'light', // 'light' | 'dark' | 'system'
  initTheme: () => {
    try {
      const saved = mmkv.getString(STORAGE_KEY);
      if (saved) {
        set({ themeMode: saved });
      } else {
        // Kh├┤ng c├│ lß╗▒a chß╗ìn ─æ├ú l╞░u -> d├╣ng mß║╖c ─æß╗ïnh s├íng.
        set({ themeMode: 'light' });
      }
    } catch (e) {
      set({ themeMode: 'light' });
    }
  },
  setThemeMode: (mode) => {
    try {
      mmkv.set(STORAGE_KEY, mode);
    } catch (e) {
      // ignore
    }
    set({ themeMode: mode });
  },
}));
